import test from 'node:test';import assert from 'node:assert/strict';
import {magnetExperiments,magnetStart,magnetAction,magnetView,magnetArtKeys,magnetArt} from '../src/magnetism.js';
import {objects,materials} from '../src/data.js';import {openSpaces,openSpaceObjects} from '../src/open-spaces.js';import {zoneExit} from '../src/zones.js';import {pathfind} from '../src/navigation.js';import {getJournalEntries} from '../src/journal.js';
test('lab hub portal, return and every experiment approach are reachable',()=>{assert.equal(zoneExit('grounds','magnetism'),'magnet');assert.equal(objects.find(o=>o.id==='magnet').to,'magnetism');for(const o of openSpaceObjects.filter(o=>o.zone==='magnetism'))assert.ok(pathfind(openSpaces.magnetism.spawn,[o.x-65,o.y+55],'magnetism').length,o.id);});
test('magnet polarity, material selectivity and coil circuit have different causal results',()=>{const initial=magnetStart();assert.match(magnetView('poles',magnetAction(initial,'same')).result,/push apart/);assert.match(magnetView('poles',magnetAction(initial,'opposite')).result,/pull together/);for(const material of ['wood','copper','aluminium'])assert.match(magnetView('materials',magnetAction(initial,material)).result,/no strong pull/);assert.match(magnetView('materials',magnetAction(initial,'iron')).result,/pulled/);const on=magnetAction(initial,'switch'),more=magnetAction(on,'turns');assert.match(magnetView('coil',on).result,/One turn lifts one/);assert.match(magnetView('coil',more).result,/Three turns lift three/);assert.match(magnetView('coil',magnetAction(more,'switch')).result,/No current/);assert.equal(magnetView('coil',magnetAction(more,'switch')).art,'coil-off-3');assert.equal((magnetArt('coil-off-3').match(/<ellipse/g)||[]).length,3);assert.equal(initial.tested,false);});
test('induction needs change, reverses pulse direction and can be repeated or reset',()=>{let s=magnetStart();for(const action of ['in','out','still','in']){s=magnetAction(s,action);assert.match(magnetView('generator',s).result,action==='still'?/no sustained/:action==='out'?/reverses/:/voltage pulse/);}assert.deepEqual(magnetAction(s,'reset'),magnetStart());});
test('all experiment choices fit native interface, have diagrams, and journal only actual trials',()=>{for(const [id,e]of Object.entries(magnetExperiments)){const initial=magnetView(id);assert.ok(initial.actions.length+1<=6);for(const [,action]of initial.actions){const v=magnetView(id,magnetAction(magnetStart(),action));assert.ok(magnetArtKeys.includes(v.art));assert.ok(magnetArt(v.art).includes('<svg'));}const visit=new Set(['magnetism-'+id]);assert.equal(getJournalEntries('experiments',new Set(),visit,objects,materials).length,0);visit.add('magnet-trial-'+id);const records=getJournalEntries('experiments',new Set(),visit,objects,materials);assert.equal(records.length,1);assert.equal(records[0].target,'magnetism-'+id);assert.equal(records[0].fact,e.fact);}});
